INSERT INTO `learning_sessions` (`id`, `syllabus_unit_id`, `transversal_competence`, `activity_type`, `sequence_activities`, `evaluation_criteria`, `evaluation_technique`, `evaluation_instrument`, `evaluation_moment`, `bibliography`, `status`, `completed_at`, `created_at`, `updated_at`) VALUES
(451, 2830, '\"CE5.C1 Aplicar  principios y valores éticos - deontológicos en su contexto social y laboral, respetando las normas del bien común y códigos de ética profesional.  ', 'teorico-practico', '[{\"moment\":\"inicio\",\"label\":\"Inicio\",\"hint\":\"Motivaci\\u00f3n, Recojo de saberes previos, Conflicto cognitivo\",\"activity\":\"El docente saluda cordialmente a los estudiantes. Y registra la asistencia. y les da labienvenida al Programa de Estudios de Mecanica de Producci\\u00f3n Industrial, y da una introducci\\u00f3n al curso luego  les hace alcance  de las normas de convivencia para un buen desarrollo de la sesi\\u00f3n de clase. Y presenta la hoja de informaci\\u00f3n: Introducci\\u00f3n a la gesti\\u00f3n de mantenimiento y formula las siguientes interrogantes \\u00bfQu\\u00e9 entiende por gesti\\u00f3n de mantenimiento?\\nLos estudiantes expresan sus respuestas, y se el docente recoge los saberes previos y refuerza los conocimientos.\\n\",\"resources\":\"Hoja de informaci\\u00f3n\",\"time\":20},{\"moment\":\"desarrollo\",\"label\":\"Desarrollo\",\"hint\":\"Construcci\\u00f3n del aprendizaje, Aplicaci\\u00f3n\",\"activity\":\"El docente entrega la hoja de informaci\\u00f3n del contenido de la clase\\u2026.\\nY cada estudiante lee la informaci\\u00f3n y con ayuda del docente sistematizan la informaci\\u00f3n a trav\\u00e9s de un mapa mental \\n\",\"resources\":\"Ordenador de ideas\",\"time\":60},{\"moment\":\"cierre\",\"label\":\"Cierre\",\"hint\":\"Metacognici\\u00f3n y evaluaci\\u00f3n\",\"activity\":\"Orientaciones sobre la ampliaci\\u00f3n del tema\\ny se da por concluida la clase.\\n\\n\",\"resources\":\"separata\",\"time\":10}]', 'Define la importancia de la UD. definiendo las documentaciones en la gestión de los equipos a tratar', 'exposición', 'Informe', 'Inicio', 'González, R. H. Mantenimiento Industrial: Organización, control y gestión.\nDuffuaa, S. et al. (2010). Sistemas de mantenimiento: planeación y control (referencia académica común).\n', 'completed', '2026-04-15 01:56:18', '2026-04-15 01:32:10', '2026-04-15 01:56:18'),
