INSERT INTO `syllabus_units` (`id`, `syllabus_indicator_id`, `session_number`, `week_range`, `execution_date`, `name`, `content`, `learning_outcome`, `evaluation_instrument`, `created_at`, `updated_at`) VALUES
(1, 1, 1, NULL, NULL, 'Introducción a los costos y presupuestos en construcción', 'Conceptos generales (costo, precio, etc.),\npresupuesto, análisis de precios unitarios,\nestructura de un presupuesto y marco\nnormativo.', 'Comprende la estructura general de un presupuesto de obra e identifica los tipos de costos y recursos que intervienen en un proyecto de construcción.', 'Guía de Observación', '2026-03-24 14:25:29', '2026-04-13 17:04:14'),
(2, 1, 2, NULL, NULL, 'Costo de mano de obra en construcción', 'Categoría de mano de obra según CAPECO, costo hora – hombre, cuadrilla y rendimientos.', 'Calcula el costo unitario de la mano de obra aplicando las leyes sociales vigentes.', 'Lista de Cotejo', '2026-03-24 14:26:42', '2026-04-13 17:04:14'),
(3, 1, 3, NULL, NULL, 'Aporte unitario de materiales de construcción ', 'Aporte unitario (concreto, mortero, encofrado,\nacero, entre otros), precio del material y\nporcentaje de desperdicios.', 'Determina el aporte unitario de materiales para las partidas representativas, considerando rendimientos y desperdicios según especificaciones.', 'Informe', '2026-03-24 14:27:22', '2026-04-13 17:04:14'),
(4, 1, 4, NULL, NULL, 'Costos de equipos, herramientas y subcontratos', 'quipos, costo hora – maquina, rendimientos,\naporte unitario, herramientas y subcontratos.', 'Calcula el costo horario de equipos de construcción.', 'Informe', '2026-03-24 14:28:04', '2026-04-13 17:04:14'),
(5, 1, 5, NULL, NULL, 'Integración del costo unitario de recursos – S10 ', 'Entorno de trabajo de S10, revisión integrada de\nS10, registrar nuevo presupuesto, insertar\ntítulos, subtítulos, generar ítems e insertar\nprecio unitario de una partida.', 'Integra los costos de materiales, mano de obra y equipos usando el software S10, configurando correctamente la base de datos de insumos.', 'Lista de Cotejo', '2026-03-24 14:28:36', '2026-04-13 17:04:14'),
(6, 2, 6, NULL, NULL, 'Análisis de Costos Unitarios – Partidas de Estructuras.', 'Elaboración de APU (estructura y\ncomponentes), análisis de partidas de\nestructuras (movimiento de tierras, concreto\nsimple) y Uso del S10 para elaborar APU de\nestructuras.', 'Elabora análisis de precios unitarios de partidas de la\nespecialidad de Estructuras usando el software S10.', 'Informe', '2026-03-24 14:29:23', '2026-04-13 17:04:14'),
(7, 2, 7, NULL, NULL, 'Análisis de Costos Unitarios – Partidas de Estructuras.', 'Elaboración de APU: estructura y componentes. Análisis de partidas de estructuras: concreto armado. Uso del S10 para elaborar APU de estructuras.', 'Elabora análisis de precios unitarios de partidas de la\nespecialidad de Estructuras usando el software S10..', 'Informe', '2026-03-24 14:29:25', '2026-04-13 17:04:14'),
(8, 2, 8, NULL, NULL, 'Análisis de Costos Unitarios – Partidas de Arquitectura.', 'APU de partidas de arquitectura (muros y\ntabiques, revoques y enlucidos, cielorrasos,\npisos y pavimentos), ingreso y procesamiento\nen S10, comparación de rendimientos y costos\nsegún zona geográfica.', 'Elabora análisis de precios unitarios de partidas de\nArquitectura usando el software S10.', 'Informe', '2026-03-24 14:29:41', '2026-04-13 17:04:14'),
(9, 2, 9, NULL, NULL, 'Análisis de Costos Unitarios – Partidas de Arquitectura', 'PU de partidas de arquitectura (zócalos,\ncontrazócalos, carpintería de madera y metálica,\ncerrajería, vidrios y cristales, pintura), ingreso y\nprocesamiento en S10 y comparación de\nrendimientos y costos según zona geográfica.', 'Elabora análisis de precios unitarios de partidas de\nArquitectura usando el software S10.', 'Informe', '2026-03-24 14:29:42', '2026-04-13 17:04:14'),
(11, 2, 10, NULL, NULL, 'Análisis de Costos Unitarios – Instalaciones Eléctricas y Sanitarias', 'APU de instalaciones sanitarias (redes de agua\nfría, agua caliente, desagüe y ventilación,\naparatos sanitarios), APU de instalaciones\neléctricas (salidas de luz, tomacorrientes,\ntableros, alimentadores) y Ingreso de partidas\nen S10.', 'Elabora APU de partidas de instalaciones sanitarias y\neléctricas con el software S10.', 'Informe', '2026-03-24 14:29:51', '2026-04-13 17:04:14'),
(12, 2, 11, NULL, NULL, 'Análisis de Costos Unitarios – Instalaciones de Gas y Obras Complementarias', 'APU de instalaciones de gas (redes internas,\nconexiones y accesorios), APU de obras\nexteriores y complementarias (cercos, veredas,\njardines).', 'Elabora APU de instalaciones de gas y obras\ncomplementarias.', 'Informe', '2026-03-24 14:29:54', '2026-04-13 17:04:14'),
(13, 6, 1, NULL, NULL, 'La computadora', '•	Concepto de computadora.\n•	Definición, ejemplos y clasificación de Hardware \n•	Definición, ejemplos y clasificación de Software.\n•	Operaciones básicas con Archivos (Comprimir, organizar, proteger, etc).', 'El estudiante identifica y reconoce la computadora y sus partes.', 'Lista de Cotejo', '2026-03-24 14:38:05', '2026-03-24 14:59:07'),
(14, 5, 1, NULL, NULL, 'Presentación del silabo e introducción ', 'La tensión eléctrica\nBaja tensión\nMedia tensión\nAlta tensión\nLa corriente eléctrica\n\n', 'Comprensión conceptual: Ser capaz de explicar que la tensión eléctrica (o voltaje) es la diferencia de potencial que actúa como la \"presión\" o fuerza necesaria para que los electrones se muevan a través de un conductor.', 'Rúbrica', '2026-03-24 14:41:29', '2026-03-26 03:12:35'),
(16, 6, 2, NULL, NULL, 'Sistemas Operativos', '•	Sistema operativo Windows, Linux, etc. \n•	Principales características de los sistemas operativos.\n•	Ventajas y desventajas de los sistemas operativos.', 'Identifica distintos tipos de sistemas operativos.', 'Prueba Escrita', '2026-03-24 14:49:11', '2026-03-24 14:59:07'),
(17, 18, 1, NULL, NULL, 'Conociendo la Unidad Didáctica ', 'Pre-test individual spell that …\nPresentación y explicación del silabo de la UD: propósito, capacidades, indicadores de logro, contenidos, metodología y sistema de evaluación.\n', 'Reconoce la organización de la unidad didáctica Comprende el concepto y la importancia de la unidad didáctica dentro de su perfil profesional', 'Lista de Cotejo', '2026-03-24 14:49:39', '2026-03-30 05:05:24'),
(22, 13, 1, NULL, NULL, 'Contabilidad Computarizada', '•	Definición\n•	Importancia\n•	Objetivos', 'Describe la contabilidad computarizada.', 'Lista de Cotejo', '2026-03-24 14:51:59', '2026-03-26 02:27:10'),
