INSERT INTO `syllabus_units` (`id`, `syllabus_indicator_id`, `session_number`, `week_range`, `execution_date`, `name`, `content`, `learning_outcome`, `evaluation_instrument`, `created_at`, `updated_at`) VALUES
(857, 217, 10, NULL, NULL, 'MANTENIMIENTO DEL SISTEMA DE CARGA DEL AUTOMOVIL', '•	Pruebas y ensayos eléctricos que\ndeterminan estado técnico de los\ncomponentes del sistema de carga\nautomotriz.\n•	Diagnóstico de fallas y averías.', 'Efectuar el mantenimiento del sistema de carga del automovil utilizando instrumentos de medicion y contrastandolas con los datos teoricos del manual del fabricante del vehiculo, justificando con calculos matematicos.', 'Guía de Observación', '2026-03-30 00:37:26', '2026-03-30 01:00:31'),
(858, 217, 11, NULL, NULL, 'MANTENIMIENTO DEL SISTEMA DE CARGA DEL AUTOMOVIL', 'Pruebas y ensayos eléctricos que\ndeterminan estado técnico de los\ncomponentes del sistema de carga\nautomotriz.\n•	Diagnóstico de fallas y averías.', 'Efectuar el mantenimiento del sistema de carga del automovil utilizando instrumentos de medicion y contrastandolas con los datos teoricos del manual del fabricante del vehiculo, justificando con calculos matematicos.', 'Prueba Escrita', '2026-03-30 00:38:03', '2026-03-30 01:00:31'),
(859, 220, 3, NULL, NULL, 'Modos de transmisiones ', 'Modos de transmisiones: \nSimplex, Half-Duplex, Full-Duplex.', 'Explicar los diferentes modos de transmisiones de datos', 'Guía de Observación', '2026-03-30 00:42:40', '2026-04-05 17:20:27'),
(860, 218, 12, NULL, NULL, 'MAGNITUDES ELECTRICAS Y ELECTRONICAS', '•	Teoría electrónica de la materia. \n•	Magnitudes eléctricas: diferencia de potencial, intensidad de corriente, resistencia y potencia. Corriente continua y corriente alterna. \n•	Ley de Ohm y ley de Joule. \n•	Efectos de la corriente eléctrica', 'Describir la relacion de las magnitudes electricas en un circuito electrico - Ley de Ohm, justificandolo con calculos matematicos.', 'Guía de Observación', '2026-03-30 00:42:56', '2026-03-30 01:00:31'),
(861, 218, 13, NULL, NULL, 'CIRCUITOS ELECTRICOS - LA BATERIA', '•	Componentes eléctricos básicos: resistencia, condensador y bobina. Circuitos eléctricos: Serie y paralelo. \n•	Asociación de resistencias y condensadores. \n•	Semiconductores: diodos y transistores\n•	Finalidad, función y componentes de la batería. \n•	Tensión y capacidad. \n•	Electrolito.\n•	Densidad del electrolito.\n•	Electrodos. \n•	Procesos de carga y descarga.', 'Describir el funcionamiento de un circuito electrico con acumuladores de energia como fuente, aplicando la Ley de Ohm y justificandolo con calculos matematicos.', 'Prueba Escrita', '2026-03-30 00:42:58', '2026-03-30 01:00:31'),
(865, 219, 14, NULL, NULL, 'MOTOR DE ARRANQUE', '•	Finalidad, función y componentes. \n•	Proceso de arranque de un motor de combustión interna. \n•	Motor de corriente continua serie.\n•	Intensidad de corriente y par de arranque.\n•	Potencia eléctrica y mecánica. \n•	Rendimiento.\n•	Devanado inducido e inductor, Colector, Escobillas, Delgas.', 'Describir el funcionamiento del sistema de arranque justificando el valor de sus magnitudes con calculos matematicos', 'Guía de Observación', '2026-03-30 00:43:18', '2026-03-30 01:00:31'),
(866, 219, 15, NULL, NULL, 'SOLENOIDE Y CIRCUITO DE CONTROL DEL MOTOR DE ARRANQUE', '•	Interruptores electromagnéticos de\nrelé.\n•	Acoplamiento con tornillo Bendix.\n•	Acoplamiento por inducido deslizante.\n•	Diagrama del circuito de control.', 'Efectuar el circuito de arranque, justificando las magnitudes de su funcionamiento y contrastandolas con los datos teoricos del manual del fabricante del vehiculo.', 'Guía de Observación', '2026-03-30 00:43:21', '2026-03-30 01:00:31'),
