(2848, 588, 1, NULL, NULL, 'Personal Introduction', 'Verb: to be\nVocabulario\nSubject pronouns\nPossessive adjectives', 'Dialogan en pares', 'Guía de Observación', '2026-04-07 01:53:19', '2026-04-07 02:02:17'),
(2849, 589, 2, NULL, NULL, 'Greetings and good byes', 'Verb: to be\nExpression\nvocabulary', 'Trabajo en pares con buela oralidad.', 'Guía de Observación', '2026-04-07 01:55:42', '2026-04-07 02:02:17'),
