(2925, 324, 10, NULL, NULL, 'Plan Contable General empresarial: Elemento 5–Patrimonio.', '• Conceptos básicos • Dinámica • Casos\nPrácticos', 'Define y Caracteriza acerca del Patrimonio Neto.', 'Lista de Cotejo', '2026-04-07 09:16:41', '2026-04-07 09:41:43'),
(2926, 324, 11, NULL, NULL, 'Casuística de la dinámica de los elementos del activo, pasivo y patrimonio', '•	Aplicación de casos prácticos', 'Aplica de casos prácticos del activo, pasivo y patrimonio', 'Rúbrica', '2026-04-07 09:18:53', '2026-04-07 09:41:43'),
(2927, 325, 12, NULL, NULL, 'Plan Contable General empresarial: Elemento 6– Gastos por naturaleza', '• Conceptos básicos • Dinámica • Casos\nPrácticos', 'Define y Caracteriza acerca de los Gastos por Naturaleza', 'Lista de Cotejo', '2026-04-07 09:22:29', '2026-04-07 09:41:43'),
(2928, 325, 13, NULL, NULL, 'Plan Contable General empresarial: Elemento 7–Ingresos por naturaleza.', '• Conceptos básicos • Dinámica • Casos\nPrácticos', 'Define y Caracteriza acerca de los Ingresos', 'Lista de Cotejo', '2026-04-07 09:26:06', '2026-04-07 09:41:43'),
